192	            })?;
193	        let adapter_info = adapter.get_info();
194	        let backend = match adapter_info.backend {
195	            wgpu::Backend::BrowserWebGpu => WgpuBackend::BrowserWebGpu,
196	            wgpu::Backend::Gl => WgpuBackend::Gl,
197	            backend => {
198	                anyhow::bail!(
