217	            "Browser graphics initialized: requested={preference:?}, selected={backend:?}, \
218	             adapter={:?}, limits={:?}, dual_source_blending={dual_source_blending}",
219	            adapter_info.name,
220	            device.limits(),
221	        );
222	
